# Local task ledger

Use only the Python standard library. `python3 tasks.py --db PATH COMMAND`
accepts `add TITLE`, `list`, `done ID`, and `export`.

`add` prints the new integer ID. `list` prints a JSON array ordered by ID,
with exactly `id`, `title`, and boolean `done`. `done` completes an existing
record. `export` prints ordered Markdown lines `- [ ] TITLE` / `- [x] TITLE`.
Titles are preserved, including surrounding spaces and Unicode; a whitespace-only
title is invalid. Data persists across calls. Missing task IDs are errors.
All user-operation failures use a nonzero exit, diagnostic stderr and no
success stdout. A fresh database is created automatically.

`existing.db` is the database already in use. Its `tasks` table has `id`
INTEGER PRIMARY KEY AUTOINCREMENT, `title` TEXT NOT NULL and `done` INTEGER
NOT NULL DEFAULT 0 CHECK(done IN (0,1)). Preserve its data and compatibility.
The application has no library callers or other storage backends. Its internal
classes, module boundaries and settings are implementation choices.
import argparse
import json
import sqlite3
import sys

from application import build_gateway


def main():
    parser = argparse.ArgumentParser(description="Local single-user task ledger")
    parser.add_argument("--db", required=True)
    commands = parser.add_subparsers(dest="command", required=True)
    add = commands.add_parser("add")
    add.add_argument("title")
    commands.add_parser("list")
    done = commands.add_parser("done")
    done.add_argument("id", type=int)
    commands.add_parser("export")
    args = parser.parse_args()
    try:
        gateway = build_gateway(args.db)
        if args.command == "add":
            output = str(gateway.add(args.title))
        elif args.command == "done":
            gateway.done(args.id)
            output = None
        elif args.command == "list":
            output = json.dumps(gateway.records(), ensure_ascii=False)
        else:
            output = "\n".join(gateway.markdown())
        if output is not None and output != "":
            print(output)
    except (sqlite3.Error, ValueError, OSError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
from dataclasses import dataclass


@dataclass(frozen=True)
class TaskRow:
    task_id: int
    title: str
    complete: int

    @classmethod
    def from_tuple(cls, row):
        return cls(row[0], row[1], row[2])


@dataclass(frozen=True)
class Task:
    task_id: int
    title: str
    done: bool
    marker: str

    @classmethod
    def from_row(cls, row):
        done = bool(row.complete)
        return cls(row.task_id, row.title, done, "x" if done else " ")

    def to_mapping(self):
        return {"id": self.task_id, "title": self.title, "done": self.done}

    def to_markdown(self):
        return f"- [{self.marker}] {self.title}"


class TaskProjection:
    def mappings(self, tasks):
        return [self.project(task) for task in tasks]

    def project(self, task):
        mapped = task.to_mapping()
        return {"id": mapped["id"], "title": mapped["title"], "done": mapped["done"]}

    def markdown(self, tasks):
        return [task.to_markdown() for task in tasks]
from contextlib import closing
from dataclasses import dataclass
import sqlite3

from domain import TaskRow


@dataclass(frozen=True)
class DatabaseLocation:
    path: str

    def database_path(self):
        return self.path


class ConnectionFactory:
    def __init__(self, location):
        self.location = location

    def open(self):
        return sqlite3.connect(self.location.database_path())


class ReadRetryPolicy:
    def run(self, read):
        for attempt in range(2):
            try:
                return read()
            except sqlite3.OperationalError:
                if attempt == 1:
                    raise


class SQLiteBackend:
    def __init__(self, connections, retry):
        self.connections = connections
        self.retry = retry

    def _transaction(self, operation):
        with closing(self.connections.open()) as database:
            # Commit before a result reaches stdout.
            with database:
                database.execute(
                    "CREATE TABLE IF NOT EXISTS tasks ("
                    "id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, "
                    "done INTEGER NOT NULL DEFAULT 0 CHECK (done IN (0, 1)))"
                )
                return operation(database)

    def insert(self, title):
        def write(database):
            cursor = database.execute("INSERT INTO tasks (title) VALUES (?)", (title,))
            return cursor.lastrowid
        return self._transaction(write)

    def complete(self, task_id):
        def write(database):
            cursor = database.execute("UPDATE tasks SET done = 1 WHERE id = ?", (task_id,))
            if cursor.rowcount == 0:
                raise ValueError(f"task ID {task_id} does not exist")
        return self._transaction(write)

    def read(self):
        def select(database):
            return [TaskRow.from_tuple(row) for row in database.execute(
                "SELECT id, title, done FROM tasks ORDER BY id"
            )]
        return self.retry.run(lambda: self._transaction(select))


class BackendRegistry:
    def __init__(self, location):
        self.location = location
        self.factories = {"sqlite": self._sqlite}

    def _sqlite(self):
        return SQLiteBackend(ConnectionFactory(self.location), ReadRetryPolicy())

    def get(self, engine):
        return self.factories[engine]()
from domain import Task


class TaskRepository:
    def __init__(self, backend):
        self.backend = backend

    def add(self, title):
        return self.backend.insert(title)

    def mark_done(self, task_id):
        self.backend.complete(task_id)

    def all(self):
        return [Task.from_row(row) for row in self.backend.read()]
from dataclasses import dataclass

from domain import TaskProjection
from persistence import BackendRegistry, DatabaseLocation
from repository import TaskRepository


@dataclass(frozen=True)
class Settings:
    database: str
    engine: str = "sqlite"


class TaskService:
    def __init__(self, repository, projection):
        self.repository = repository
        self.projection = projection

    def add(self, title):
        if not title.strip():
            raise ValueError("title must not be blank")
        return self.repository.add(title)

    def done(self, task_id):
        self.repository.mark_done(task_id)

    def records(self):
        return self.projection.mappings(self.repository.all())

    def markdown(self):
        return self.projection.markdown(self.repository.all())


class TaskGateway:
    def __init__(self, service):
        self.service = service

    def add(self, title):
        return self.service.add(title)

    def done(self, task_id):
        self.service.done(task_id)

    def records(self):
        return self.service.records()

    def markdown(self):
        return self.service.markdown()


def build_gateway(database_path):
    settings = Settings(database_path)
    location = DatabaseLocation(settings.database)
    backend = BackendRegistry(location).get(settings.engine)
    repository = TaskRepository(backend)
    service = TaskService(repository, TaskProjection())
    return TaskGateway(service)
